function bstToGst(root) {
  const all = [];
  const collect = n => {
    if (!n) return;
    all.push(n.val);
    collect(n.left);
    collect(n.right);
  };
  collect(root);
  // Each node still holds its original key when it is rewritten (parents go first).
  const rewrite = n => {
    if (!n) return;
    let total = 0;
    for (const v of all) if (v >= n.val) total += v;
    n.val = total;
    rewrite(n.left);
    rewrite(n.right);
  };
  rewrite(root);
  return root;
}

