function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const small = size === 'small';
  const count = small ? 1 + pick(8) : 90 + pick(11);
  const top = small && rand() < 0.7 ? 20 : 100;
  const values = [];
  for (let v = 0; v <= top; v++) values.push(v);
  // Shuffle, then insert the first count values: a random BST shape.
  for (let i = values.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [values[i], values[j]] = [values[j], values[i]];
  }
  const order = values.slice(0, count);
  if (rand() < (small ? 0.2 : 0.3)) { const rising = rand() < 0.5; order.sort((a, b) => (rising ? a - b : b - a)); }
  let root = null;
  for (const value of order) {
    const node = { val: value, left: null, right: null };
    if (!root) { root = node; continue; }
    let at = root;
    for (;;) {
      const side = value < at.val ? 'left' : 'right';
      if (!at[side]) { at[side] = node; break; }
      at = at[side];
    }
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
